:root {
  /* Colors */
  --color-onyx-canvas: #0a0a0a;
  --color-carbon-scrim: #0a0a0aa3;
  --color-graphite-panel: #191919;
  --color-frosted-glass: #fafafa14;
  --color-paper: #ffffff;
  --color-fog-ink: #fafafa;
  --color-mist-caption: #ffffffa3;
  --color-ash-caption: #a7a7a7;
  --color-quartz-hairline: #ffffff14;
  --color-frosted-border: #fafafa29;
  --color-steel-border: #ffffff3d;
  --color-signal-cobalt: #0044ff;
  --color-amethyst-twin: #a65cff;

  /* Typography — Font Families */
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-jetbrains-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-pp-mondwest: "PP Mondwest", "VT323", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1;
  --tracking-small: 1px;
  --text-caption: 12px;
  --leading-caption: 1.333;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.571;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.25px;
  --text-subheading: 24px;
  --leading-subheading: 1.333;
  --tracking-subheading: -0.25px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: -1px;
  --text-heading: 40px;
  --leading-heading: 1.05;
  --tracking-heading: -1.2px;
  --text-heading-lg: 96px;
  --leading-heading-lg: 1.042;
  --tracking-heading-lg: -2px;
  --text-display: 160px;
  --leading-display: 0.875;
  --tracking-display: -2.3px;
  --text-pixel-splice: 120px;
  --leading-pixel-splice: 0.833;
  --tracking-pixel-splice: -2px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-120: 120px;
  --spacing-124: 124px;
  --spacing-140: 140px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1512px;
  --layout-gutter: 124px;
  --layout-section-gap: 160px;
  --layout-card-padding: 48px;
  --layout-element-gap: 16px;
  --layout-nav-height: 88px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-full: 50%;

  /* Named Radii */
  --radius-cards: 8px;
  --radius-buttons: 8px;
  --radius-tags: 8px;
  --radius-nav: 8px;
  --radius-images: 4px;
  --radius-inner-tiles: 4px;
  --radius-small-elements: 4px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-sm: rgba(0, 0, 0, 0.45) 0px 2px 4px 0px, rgba(255, 255, 255, 0.8) 0px 0px 0px 1px inset;

  /* Surfaces */
  --surface-onyx-canvas: #0a0a0a;
  --surface-graphite-panel: #191919;
  --surface-frosted-glass: #fafafa14;
  --surface-carbon-scrim: #0a0a0aa3;
  --surface-paper: #ffffff;
}

